=You are a security news editor. Based on the CISA advisory below, write a draft explainer article for IT staff.

Language: {{ $('Settings').first().json.lang === 'en' ? 'English' : 'Japanese (日本語)' }}

Rules:
- Do not add any facts or numbers that are not in the original
- Do not translate or copy the original sentence by sentence. Use your own structure and words
- Keep CVE IDs, product names and versions exactly as in the original
- Title: {{ $('Settings').first().json.lang === 'en' ? 'within 100 characters' : '60字以内' }}
- Body length: {{ $('Settings').first().json.lang === 'en' ? 'about 200-350 words' : '1000字以内' }}
- Use exactly these three h2 headings in body_html: {{ $('Settings').first().json.lang === 'en' ? 'What happened / Affected products / What to do' : '何が起きたか / 影響を受ける製品 / やるべきこと' }}
- End body_html with a source line that links to the original URL
- Output JSON only. Do not write anything before or after the JSON

JSON format:
{
  "title": "...",
  "summary": "up to 3 sentences",
  "body_html": "<h2>...</h2><p>...</p>...<p>Source: <a href=\"ORIGINAL_URL\">CISA</a></p>",
  "tags": ["..."],
  "source_url": "ORIGINAL_URL"
}

Original title: {{ $json.title }}
Original URL: {{ $json.link }}
Original text:
{{ $json.contentSnippet }}

parameters.jsCode:
const lang = $('Settings').first().json.lang || 'ja';

// 1. Claude の返事から text のブロックを探す
const blocks = $input.item.json.content || [];
const textBlock = blocks.find(b => b.type === 'text');
const raw = textBlock ? textBlock.text : '';

// 元の RSS 記事
const src = $('Limit').item.json;
const srcText = (src.title || '') + ' ' + (src.contentSnippet || src.content || '');

const errors = [];
const warnings = [];

// 2. JSON として読めるか（{ から } までを取り出す）
let draft = null;
try {
  const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
  const cleaned = start >= 0 && end > start ? raw.slice(start, end + 1) : raw;
  draft = JSON.parse(cleaned);
} catch (e) {
  errors.push('JSONとして読めない：' + e.message);
}

if (draft) {
  // 3. 必須の項目
  for (const key of ['title', 'summary', 'body_html', 'source_url']) {
    if (!draft[key]) errors.push(`${key} がない`);
  }
  const title = draft.title || '';
  const body = draft.body_html || '';
  const bodyText = body.replace(/<[^>]+>/g, ' ');

  // 4. 長さ（言語ごと）
  if (lang === 'en') {
    const words = bodyText.split(/\s+/).filter(Boolean).length;
    if (title.length > 100) errors.push(`タイトルが長い（${title.length}文字）`);
    if (words < 150) warnings.push(`本文が短い（${words}語）`);
    if (words > 500) warnings.push(`本文が長い（${words}語）`);
  } else {
    const chars = bodyText.replace(/\s+/g, '').length;
    if (title.length > 60) errors.push(`タイトルが長い（${title.length}字）`);
    if (chars < 600) warnings.push(`本文が短い（${chars}字）`);
    if (chars > 1500) warnings.push(`本文が長い（${chars}字）`);
  }

  // 5. 出典リンク
  if (draft.source_url !== src.link) errors.push('source_url が RSS のリンクと違う');
  if (!body.includes(src.link)) errors.push('本文に出典リンクがない');

  // 6. 必須の見出し（言語ごと）
  const heads = lang === 'en'
    ? ['What happened', 'Affected products', 'What to do']
    : ['何が起きたか', '影響を受ける製品', 'やるべきこと'];
  for (const h of heads) {
    if (!body.toLowerCase().includes(h.toLowerCase())) warnings.push(`見出し「${h}」がない`);
  }

  // 7. CVE 番号：原文にないものは NG
  const cves = [...new Set((title + ' ' + bodyText).match(/CVE-\d{4}-\d{4,}/g) || [])];
  for (const cve of cves) {
    if (!srcText.includes(cve)) errors.push(`原文にないCVE番号：${cve}`);
  }

  // 8. 数字：原文にないものは警告
  const toHalf = s => s.replace(/[０-９．]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));
  const srcHalf = toHalf(srcText);
  const nums = [...new Set(toHalf(bodyText).match(/\d+(\.\d+)?/g) || [])];
  const unknown = nums.filter(n => n.length >= 2 && !srcHalf.includes(n));
  if (unknown.length) warnings.push(`原文に見つからない数字：${unknown.slice(0, 10).join(', ')}`);

  // 9. 類似度（英語版だけ）：生成文の「3語の並び」のうち、原文にもあるものの割合
  if (lang === 'en') {
    const tri = s => {
      const w = s.toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/).filter(Boolean);
      const set = new Set();
      for (let i = 0; i < w.length - 2; i++) set.add(w.slice(i, i + 3).join(' '));
      return set;
    };
    const gen = tri(bodyText), org = tri(srcText);
    const shared = [...gen].filter(x => org.has(x)).length;
    const ratio = gen.size ? shared / gen.size : 0;
    const pct = Math.round(ratio * 100);
    if (ratio > 0.5) errors.push(`原文と似すぎ（${pct}%）`);
    else if (ratio > 0.3) warnings.push(`原文と少し似ている（${pct}%）`);
  }
}
// 10. コスト（100万トークンあたりのドル）
const usage = $input.item.json.usage || {};
const model = $input.item.json.model || '';
const PRICES = { haiku: [0.10, 0.50], sonnet: [2, 10], opus: [4, 20] };
const key = Object.keys(PRICES).find(k => model.includes(k)) || 'haiku';
const [pIn, pOut] = PRICES[key];
const inTok = usage.input_tokens || 0;
const outTok = usage.output_tokens || 0;
const costUsd = Number(((inTok * pIn + outTok * pOut) / 1e6).toFixed(6));
return {
  json: {
    pass: errors.length === 0,
    lang,
    errors,
    warnings,
    draft,
    source_title: src.title,
    source_url: src.link,
    raw_end: raw.slice(-150),
    model, input_tokens: inTok, output_tokens: outTok, cost_usd: costUsd,
  },
};

